def main():
    external={}
    for key in ['reference','clinical','commercial']:
        external[key]=json.loads((P/(key+'_blocks.json')).read_text())
    clinical=external['clinical']['blocks']
    clinical.insert(2,dict(type='p',text='Reading the trials: intention-to-treat (ITT) analyzes participants according to randomized assignment; modified ITT imposes additional inclusion rules. A crossover gives the same patient different treatments for separate attacks. VAS is a visual analog symptom scale. PGI-C is Patient Global Impression of Change; initial relief requires “at least a little better” on two consecutive ratings. OLE means open-label extension, where treatment is known. SAP means statistical analysis plan. A confidence interval (CI) describes sampling uncertainty under the analysis assumptions, not every source of bias.'))
    clinical.insert(-1,dict(type='p',text='A prognostic factor predicts outcome regardless of treatment; a predictive factor changes the treatment advantage. Test the treatment-by-subgroup interaction directly: significance in one subgroup but not another is not evidence of an interaction. Vary plausible cutoffs, inspect a few high-frequency patients, adjust for baseline and region, and seek independent replication. Different regional or severity mixtures can even reverse pooled comparisons, the pattern called Simpson’s paradox. Prespecification of these specific interactions was not established, and individual-patient data needed to perform them were unavailable.'))
    clinical.insert(-1,dict(type='p',text='For a future trial such as CREAATE, planned power assumes a chosen effect and variance; predictive success averages over uncertainty in both, the control response and population. Small favorable studies may overestimate effects through chance selection, often called winner’s curse. Fewer participants reduce power only with effect size, variation, allocation and analysis otherwise comparable. Post-hoc observed power adds no independent evidence to a completed trial’s effect estimate and confidence interval.'))
    for b in clinical:
        if b.get('text','').startswith('Other denominator changes are explainable.'):
            b['text']=b['text'].replace('Other denominator changes are explainable.', 'Other denominator changes require explicit reconciliation.').replace('the registry reports 40 completing the attack phase, with 23 additional patients categorized as having met primary-analysis criteria and ten withdrawing.', 'one withdrew in the initial phase, leaving 73 entering the attack phase. The registry then reports 40 completing, 23 categorized as having met primary-analysis criteria and ten withdrawing. The 40 plus 23 categories do not fully reconcile the publication’s 62-person primary set; that remaining difference needs clarification.')
        if b.get('text','').startswith('CHAPTER-3 recorded any adverse event'):
            b['text'] += ' Severity grades describe intensity; “serious” refers to consequences such as hospitalization or life threat and is a different classification. Investigator attribution is a causality assessment, not proof that an event cannot be drug-related.'
        if 'GGT elevation' in b.get('text',''):
            b['text']=b['text'].replace('GGT elevation','elevation of gamma-glutamyl transferase (GGT), a laboratory enzyme marker')
    blocks=[]
    for key in ['opening','taxonomy','reference','biology','clinical','commercial','debates','hypotheses','quant','expectations','actions']:
        blocks.extend(external[key]['blocks'] if key in external else sections[key])
    def normalize(s):
        return re.sub(r'\[([A-Z]\d+(?:,\s*[A-Z]\d+)+)\]',lambda m:' '.join('['+x.strip()+']' for x in m.group(1).split(',')),s)
    for b in blocks:
        if 'text' in b: b['text']=normalize(b['text'])
        if b['type'] in ['h1','h2']: b['text']=b['text'].replace(':','').replace('—',' ')
        if b['type']=='table': b['rows']=[[normalize(v) for v in row] for row in b['rows']]
        if b.get('text','').startswith('**Observed PHVS inputs; derived approximation.'):
            b['text']+=' [R2]'
        if b.get('text','').startswith('S(c,t) is the probability'):
            b['text']=b['text'].replace('S(c,t) is the probability that start cohort c remains on treatment at time t.', 'For the patient-month calculation, S(c,t) is the average probability of remaining treated over the cohort’s exposed part of period t, obtained by integrating survival over that interval. It is not the end-of-period survivor fraction multiplied by a full period.')
        if b.get('text','').startswith('The legal company is Pharvaris'):
            b['text']+=' NDA means New Drug Application, the US marketing application; acceptance starts review and is not approval. BLA is the corresponding biologic marketing application. A PDUFA date is the FDA’s target action date, not a promise of approval.'
    all_sources=sources+sum((external[k]['sources'] for k in external),[])
    ids=[s['id'] for s in all_sources]
    assert len(ids)==len(set(ids)), 'duplicate source identifiers'
    payload=dict(title='Pharvaris investment research assessment',subtitle='Clinical evidence commercial adoption and a framework for valuation\nResearch date 6 October 2026',blocks=blocks,sources=all_sources,method='The supplied deck, workbook and essays were reviewed first as reference material rather than instructions. A bounded discovery pass covered registries, protocols, statistical analysis plans, papers, labels, filings, original presentations, epidemiology, payer policies and launch disclosures; the strongest leads received targeted follow-up. Three parallel workstreams audited clinical evidence, commercial evidence and supplied examples, followed by integration and selected primary-source checks. No paid data, bulk scraping, large OCR job, primary interview or individual-patient fitting was performed. Public registries and the RAPIDe-1 and CHAPTER-1 protocol/SAP files were retained locally. Complete pivotal SAPs, full registry amendment histories, patient-level outcome data, representative claims and product-level consensus were unavailable. The large 2025 annual filing was not fully retrievable in the browser; current interim statements and specific license disclosures supplied the financial cross-checks. Arithmetic uses stated published counts or explicitly hypothetical inputs. The memo does not infer unknown dropout reasons or fabricate records. Source repetition is not independent replication. Research stopped where more precision required inaccessible data or weak proxies; the resulting limitations are attached to the model variables they affect.')
    (P/'memo_content.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2))
    print('Final content assembled:',len(blocks),'blocks;',len(all_sources),'sources')

if __name__=='__main__': main()
